sys_script_include.script:
var checkTreasuryBandLimit = Class.create();
checkTreasuryBandLimit.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	getBandingGroup: function(region, type, transaction_Amount, currency) {
        var isRquestError = false;
        var banding_Group = '';
        try {
            ///var gr = new GlideRecord('x_hsb11_hsbcmss_sw_hsbc_swb_outbound_table');
            var stsToken = gs.getProperty('x_hsb11_mss_tsd.eventOutbound_STS_getToken');

            var r = new sn_ws.RESTMessageV2('HSBC STS API', 'Get The type Of group');
            r.setStringParameterNoEscape('getToken', stsToken);

            var body = this.build_sendout_body(region, type, transaction_Amount, currency);

            var toSend = JSON.stringify(body);
            r.setRequestBody(toSend);


            var response = r.execute(); //Send request, will throw exception.
            var responseBody = response.getBody();

            var resp_parsed = JSON.parse(responseBody); //will throw exception, but http status already got.
            //var httpStatus = response.getStatusCode();
            var httpStatus = resp_parsed.Status || resp_parsed.status;
            if (httpStatus == '202' || httpStatus == '200') {
                banding_Group = resp_parsed.banding_Group;
                return banding_Group;

            } else {
                isRquestError = true;
                gs.error('Script Include - MSS_Treasury_Utils:- Unknown exception while call STS transaction threshold API');
                return false;
            }
        } catch (e) {
            comments = 'Script Include - MSS_Treasury_Utils:- Unknown exception while while call STS transaction threshold API  ' + e.message;
            gs.error(comments);
            isRquestError = true;
        }
    },
	//because the API of getting banding group is not read,so use below function to test
    getBandingGroup1: function() {
        return 'Band4';
    },
    getUserGroups: function() {
        //var userId = gs.getParameter('sysparm_user_id');//current user id
        var userId = gs.getUserID();
        var groups = [];
        //search sys_user_grmember table
        var gr = new GlideRecord('sys_user_grmember');
        gr.addQuery('user', userId);
        // gr.groupBy('group');
        gr.query();
        while (gr.next()) {
            groups.push({
                sys_id: gr.getValue('group'), //group ID
                name: gr.group.getDisplayValue() //group displayNme
            });
        }
        gs.info("groups JSON------------TTTTTTTTTTTTTTTTTT" + JSON.stringify(groups));
        return JSON.stringify(groups); //return JSON data
    },
    checkGroup: function() {
        var taskSysId = this.getParameter('sysparm_task_sysid');
        try {
            var grCaseTask = new GlideRecord('x_hsb11_mss_tsd_treasury_case_task');
            grCaseTask.addQuery('sys_id', taskSysId);
            grCaseTask.query();
            if (!grCaseTask.next()) {
                return;
            }
			gs.info("taskSysId222");
            var grCase = new GlideRecord('x_hsb11_mss_tsd_treasury_case');
            grCase.addQuery('sys_id', grCaseTask.instruction_case);
            grCase.query();
			gs.info("taskSysId333");
            if (!grCase.next()) {
                return;
            }

            var userGroupBandNameNumber = null;
			var result;
            //var bandingGroup = getBandingGroup(grCase.market,grCase.instruction_type,grCase.TransactionAmount,grCase.Currency);
			//because the API of getting banding group is not read,so use below function to test
            var bandingGroup = this.getBandingGroup1();
            var userGroups = this.getUserGroups();
            userGroups = JSON.parse(userGroups);
			gs.info("bandingGroup="+bandingGroup+'userGroups='+userGroups);
            userGroups.forEach(grGroup => {
                if (grGroup.name.indexOf('Band') > -1 && (grGroup.name.slice(-1) < userGroupBandNameNumber || userGroupBandNameNumber == null)) {
                    userGroupBandNameNumber = grGroup.name;
                }
            });
            gs.info('HHHHHHHHHH--' + userGroupBandNameNumber);

            if (userGroupBandNameNumber.indexOf('Band') > -1) {
                if (userGroupBandNameNumber > Number(bandingGroup.slice(-1))) {
                    //return false;
					result = 'false';
                    //return '1'; //You do not have sufficient permissions
                } else {
                    return 'true';
					//result = 'true';
                    //return '2'; //Can approve
                }
            } else {
                return 'false';
				//result = 'false';
                //return '3'; //Does not belong to the Bind group and cannot approve
            }
			//return result;
			//this.setValue('answer',result);
        } catch (ex) {
            gs.error('Script Include - MSS_Treasury_Utils:- Exception while checking isCallback for ObjectID: ' + objectID + '. Error: ' + ex.message);
        }
    },
    type: 'checkTreasuryBandLimit'
});
